package com.beatoflove.standardcalculator;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import okhttp3.*;import org.json.*;import java.util.*;import java.util.concurrent.TimeUnit;
/** Only starts for a visible Markets panel. No provider credentials bundled. */
final class MarketStream extends PanelUi {
 final Handler main=new Handler(Looper.getMainLooper());final OkHttpClient http=new OkHttpClient.Builder().pingInterval(20,TimeUnit.SECONDS).readTimeout(0,TimeUnit.SECONDS).build(); final SharedPreferences prefs;
 WebSocket ws;int generation;boolean running;int attempts;String kind;boolean automatic;TextView status;final Map<String,TextView> values=new LinkedHashMap<>();final Map<String,Long> times=new HashMap<>();final Map<String,Double> prices=new HashMap<>();final Map<String,String> detail=new HashMap<>();Runnable retry,heartbeat,stale,snapshotPoll; final Map<String,String> sources=new HashMap<>(); final Map<String,Long> referenceAttempts=new HashMap<>();
 static final String[] CRYPTO={"BTCUSDT","ETHUSDT","SOLUSDT","BNBUSDT","XRPUSDT","ADAUSDT","DOGEUSDT"},FX={"EUR/USD","GBP/USD","USD/JPY","USD/THB","USD/CHF","AUD/USD"},METAL={"XAU/USD","XAG/USD","XPT/USD","XPD/USD"};
 MarketStream(Activity a){super(a);prefs=a.getSharedPreferences("live_markets53",0);}
 void stop(){if(running){SharedPreferences.Editor save=prefs.edit();for(String symbol:prices.keySet()){try{save.putString("q:"+symbol,new JSONObject().put("p",prices.get(symbol)).put("t",times.get(symbol)).put("source",sources.get(symbol)).toString());}catch(Exception ignored){}}save.apply();}running=false;generation++;if(retry!=null)main.removeCallbacks(retry);if(heartbeat!=null)main.removeCallbacks(heartbeat);if(stale!=null)main.removeCallbacks(stale);if(snapshotPoll!=null)main.removeCallbacks(snapshotPoll);if(ws!=null){ws.cancel();ws=null;}}
 void attach(LinearLayout l,String mode,TextView external,boolean auto,String chosen){stop();kind=mode;automatic=auto;running=true;attempts=0;values.clear();times.clear();prices.clear();detail.clear();sources.clear();status=external;String[] symbols=kind.equals("Crypto")?CRYPTO:kind.equals("Forex")?FX:METAL;for(String s:symbols){if(!chosen.equals("All symbols")&&!chosen.equals(s))continue;LinearLayout r=row();r.setBackground(bg(CARD));TextView name=text(s,16,WHITE,true);r.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView v=text("—",15,WHITE,true);v.setGravity(android.view.Gravity.END);r.addView(v,new LinearLayout.LayoutParams(0,-2,2));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.setMargins(0,dp(2),0,dp(2));l.addView(r,rp);values.put(s,v);try{JSONObject j=new JSONObject(prefs.getString("q:"+s,""));long stamp=j.getLong("t");double p=j.getDouble("p");if(stamp>0&&stamp<=System.currentTimeMillis()+300000&&Double.isFinite(p)&&p>0){times.put(s,stamp);prices.put(s,p);detail.put(s,"Cached");sources.put(s,j.optString("source",kind.equals("Crypto")?"Binance":"Twelve Data"));paint(s);}}catch(Exception ignored){}}l.addView(text(automatic?(kind.equals("Crypto")?"Binance spot · USDT is not USD":"Indicative quotes · stream / snapshot fallback"):(kind.equals("Crypto")?"Binance latest trade snapshot · USDT":kind.equals("Forex")?"Frankfurter daily reference · not tradable quotes":"Gold API latest available · USD/troy oz"),12,MUTE,false));if(automatic&&!kind.equals("Crypto")){link(l,"biquote source","https://biquote.io/");action(l,"Optional Twelve Data streaming key",()->{EditText key=new EditText(a);key.setSingleLine();key.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);new AlertDialog.Builder(a).setTitle("Twelve Data personal API key").setMessage("Session only; no key saved or bundled. Provider plan must allow these symbols. For distributed use configure an authorized backend.").setView(key).setPositiveButton("Connect",(d,w)->{personalKey=key.getText().toString().trim();reconnect();}).setNegativeButton("Cancel",null).show();});}if(automatic){connect();}else startReference();stale=new Runnable(){public void run(){if(!running)return;for(String s:values.keySet())paint(s);if(kind!=null&&!kind.equals("Crypto")&&status.getText().toString().startsWith("Receiving")&&values.keySet().stream().noneMatch(k->System.currentTimeMillis()-times.getOrDefault(k,0L)<120000))status.setText("No recent ticks · last available quotes");main.postDelayed(this,15000);}};if(automatic)main.postDelayed(stale,15000);}
 void referenceOnce(int gen){for(String symbol:new ArrayList<>(values.keySet())){String[] pair=symbol.split("/");PriceService.reference(pair[0],pair[1],(j,e)->{if(!running||gen!=generation||j==null)return;try{if(!pair[0].equals(j.getString("base"))||!pair[1].equals(j.getString("quote")))return;long stamp=java.time.LocalDate.parse(j.getString("date")).atStartOfDay(java.time.ZoneOffset.UTC).toInstant().toEpochMilli();if(!automatic||!prices.containsKey(symbol)||sources.getOrDefault(symbol,"").equals("Frankfurter"))acceptSnapshot(symbol,j.getDouble("rate"),stamp,"Frankfurter","Daily reference");}catch(Exception ignored){}});}}
 void metalFallback(int gen){for(String symbol:new ArrayList<>(values.keySet()))if(!prices.containsKey(symbol)||sources.getOrDefault(symbol,"").equals("Gold API"))PriceService.metal(symbol.substring(0,3),(d,e)->{if(!running||gen!=generation||d==null)return;try{if(!prices.containsKey(symbol)||sources.getOrDefault(symbol,"").equals("Gold API"))acceptSnapshot(symbol,d.price,java.time.OffsetDateTime.parse(d.updatedAt).toInstant().toEpochMilli(),"Gold API","Latest available");}catch(Exception ignored){}});}
 void startReference(){final int gen=++generation;status.setText("Fetching latest available · no streaming");final int[] remaining={values.size()},success={0};Runnable done=()->{if(--remaining[0]==0)status.setText("Latest available · "+success[0]+" / "+values.size()+" updated · manual refresh");};
  for(String symbol:new ArrayList<>(values.keySet())){if(kind.equals("Forex")){String[] pair=symbol.split("/");PriceService.reference(pair[0],pair[1],(j,e)->{if(!running||gen!=generation)return;try{if(j!=null&&pair[0].equals(j.getString("base"))&&pair[1].equals(j.getString("quote"))){long t=java.time.LocalDate.parse(j.getString("date")).atStartOfDay(java.time.ZoneOffset.UTC).toInstant().toEpochMilli();if(acceptSnapshot(symbol,j.getDouble("rate"),t,"Frankfurter","Daily reference"))success[0]++;}}catch(Exception ignored){}done.run();});}
  else if(kind.equals("Crypto")){PriceService.cryptoLatest(symbol,(j,e)->{if(!running||gen!=generation)return;try{if(j!=null&&symbol.equals(j.getString("symbol"))&&acceptSnapshot(symbol,j.getDouble("lastPrice"),j.getLong("closeTime"),"Binance","Latest snapshot"))success[0]++;}catch(Exception ignored){}done.run();});}
  else{PriceService.metal(symbol.substring(0,3),(d,e)->{if(!running||gen!=generation)return;try{if(d!=null&&symbol.startsWith(d.symbol)&&"USD".equals(d.currency)&&acceptSnapshot(symbol,d.price,java.time.OffsetDateTime.parse(d.updatedAt).toInstant().toEpochMilli(),"Gold API","Latest available"))success[0]++;}catch(Exception ignored){}done.run();});}}
 }
 String personalKey="";void reconnect(){if(!running)return;generation++;if(ws!=null)ws.cancel();if(retry!=null)main.removeCallbacks(retry);if(heartbeat!=null)main.removeCallbacks(heartbeat);if(snapshotPoll!=null)main.removeCallbacks(snapshotPoll);for(String s:values.keySet())if(prices.containsKey(s)){detail.put(s,"Cached");paint(s);}attempts=0;connect();}
 void connect(){if(!running)return;boolean crypto=kind.equals("Crypto");if(!crypto&&personalKey.isEmpty()){startPublicStream();return;}final int gen=++generation;String url;if(crypto){StringJoiner j=new StringJoiner("/");for(String s:values.keySet())j.add(s.toLowerCase(Locale.ROOT)+"@ticker");url="wss://stream.binance.com:443/stream?streams="+j;}else{url="wss://ws.twelvedata.com/v1/quotes/price?apikey="+android.net.Uri.encode(personalKey);}status.setText("Connecting…");if(!crypto)main.postDelayed(()->{if(running&&gen==generation&&values.keySet().stream().noneMatch(k->detail.getOrDefault(k,"").startsWith("Stream"))){if(ws!=null)ws.cancel();if(heartbeat!=null)main.removeCallbacks(heartbeat);startSnapshots();}},15000);ws=http.newWebSocket(new Request.Builder().url(url).build(),new WebSocketListener(){@Override public void onOpen(WebSocket socket,Response r){main.post(()->{if(!running||gen!=generation)return;status.setText("Connected · awaiting verified quotes");if(!crypto){try{JSONObject j=new JSONObject();j.put("action","subscribe");j.put("params",new JSONObject().put("symbols",String.join(",",values.keySet())));socket.send(j.toString());}catch(Exception ignored){}heartbeat=new Runnable(){public void run(){if(!running||gen!=generation)return;socket.send("{\"action\":\"heartbeat\"}");main.postDelayed(this,10000);}};main.postDelayed(heartbeat,10000);}});}@Override public void onMessage(WebSocket socket,String raw){try{JSONObject j=new JSONObject(raw);if(crypto){JSONObject q=j.getJSONObject("data");String s=q.getString("s");double p=q.getDouble("c");long t=q.getLong("E");String ch=q.optString("P","");main.post(()->quote(gen,s,p,t,ch.isEmpty()?"":"24h "+ch+"%"));}else{String event=j.optString("event");if(event.equals("price")){String s=j.getString("symbol");double p=j.getDouble("price");long t=j.getLong("timestamp");if(t<100000000000L)t*=1000;final long time=t;main.post(()->quote(gen,s,p,time,""));}else if(event.equals("subscribe-status")){String stat=j.optString("status");main.post(()->{if(running&&gen==generation)status.setText("Subscription: "+stat+" · awaiting quotes / check plan");});}}}catch(Exception ignored){}}@Override public void onFailure(WebSocket s,Throwable t,Response r){main.post(()->closed(gen));}@Override public void onClosed(WebSocket s,int c,String r){main.post(()->closed(gen));}});}
 void startPublicStream(){
 final int gen=++generation;status.setText("Connecting to biquote stream…");if(kind.equals("Forex"))referenceOnce(gen);else if(kind.equals("Metals"))metalFallback(gen);
 final boolean[] subscribed={false},received={false};
 // SignalR JSON protocol, direct WebSocket (skip negotiation). If the server disallows it,
 // fall back to documented HTTPS snapshots, not fabricated live quotes.
 ws=http.newWebSocket(new Request.Builder().url("wss://biquote.io/hubs/tick").build(),new WebSocketListener(){
  @Override public void onOpen(WebSocket socket,Response response){socket.send("{\"protocol\":\"json\",\"version\":1}\u001e");}
  @Override public void onMessage(WebSocket socket,String raw){main.post(()->{if(!running||gen!=generation)return;
   for(String frame:raw.split("\u001e")){if(frame.trim().isEmpty())continue;try{JSONObject j=new JSONObject(frame);
    if(!subscribed[0]&&!j.has("type")&&!j.has("error")){org.json.JSONArray symbols=new org.json.JSONArray();for(String s:values.keySet())symbols.put(s.replace("/",""));
     socket.send(new JSONObject().put("type",1).put("invocationId","1").put("target","Subscribe").put("arguments",new org.json.JSONArray().put(symbols)).toString()+"\u001e");subscribed[0]=true;continue;}
    if(j.optInt("type")==1&&j.optString("target").equalsIgnoreCase("ReceiveTick")){JSONObject q=j.getJSONArray("arguments").getJSONObject(0);String code=q.getString("symbol");if(!code.matches("[A-Z]{6}"))continue;String sym=code.substring(0,3)+"/"+code.substring(3);if(!values.containsKey(sym))continue;double bid=q.getDouble("bid"),ask=q.getDouble("ask");long time=java.time.Instant.parse(q.getString("time")).toEpochMilli();if(bid<=0||ask<bid||!Double.isFinite(bid)||!Double.isFinite(ask))continue;if(acceptSnapshot(sym,(bid+ask)/2,time,"biquote MT5","Stream mid")){received[0]=true;status.setText("Receiving biquote ticks · indicative MT5 mid");}}
    if(j.optInt("type")==7||j.has("error")){publicFallback(gen);return;}
   }catch(Exception ignored){}}
  });}
  @Override public void onFailure(WebSocket socket,Throwable e,Response r){main.post(()->publicFallback(gen));}
  @Override public void onClosed(WebSocket socket,int code,String reason){main.post(()->publicFallback(gen));}
 });
 main.postDelayed(()->{if(running&&gen==generation&&!received[0])publicFallback(gen);},12000);
 heartbeat=new Runnable(){public void run(){if(!running||gen!=generation)return;if(ws!=null)ws.send("{\"type\":6}\u001e");main.postDelayed(this,15000);}};main.postDelayed(heartbeat,15000);
 }
 void publicFallback(int gen){if(!running||gen!=generation)return;generation++;if(ws!=null){ws.cancel();ws=null;}if(heartbeat!=null)main.removeCallbacks(heartbeat);startSnapshots();}
 void startSnapshots(){
 final int gen=++generation;status.setText("Fetching automatic market snapshots…");if(kind.equals("Forex"))referenceOnce(gen);else if(kind.equals("Metals"))metalFallback(gen);
 snapshotPoll=new Runnable(){public void run(){if(!running||generation!=gen)return;
 PriceService.snapshots(values.keySet().toArray(new String[0]),(data,error)->{
 if(!running||generation!=gen)return;int count=0;
 if(data!=null)for(int i=0;i<data.length();i++){JSONObject q=data.optJSONObject(i);if(q==null)continue;try{
 String code=q.getString("symbol");if(!code.matches("[A-Z]{6}"))continue;String s=code.substring(0,3)+"/"+code.substring(3);if(!values.containsKey(s))continue;
 double bid=q.getDouble("bid"),ask=q.getDouble("ask");long t=java.time.Instant.parse(q.getString("time")).toEpochMilli();
 if(bid<=0||ask<bid||!Double.isFinite(bid)||!Double.isFinite(ask)||t<=0||t>System.currentTimeMillis()+300000)continue;
 if(acceptSnapshot(s,(bid+ask)/2,t,"biquote MT5","Snapshot mid")) count++;
 }catch(Exception ignored){}}
 if(count==0){for(String s:values.keySet())if(prices.containsKey(s)&&!sources.getOrDefault(s,"").equals("Frankfurter")&&!sources.getOrDefault(s,"").equals("Gold API")){detail.put(s,"Cached");paint(s);}}
 status.setText(count>0?"Automatic snapshots · "+count+" / "+values.size()+" · 60 s refresh":"Market snapshot unavailable · cached / daily reference if available"+(error==null?"":" · "+error));
 if(kind.equals("Forex"))for(String s:values.keySet())if((!prices.containsKey(s)||sources.getOrDefault(s,"").equals("Frankfurter"))&&System.currentTimeMillis()-referenceAttempts.getOrDefault(s,0L)>900000){referenceAttempts.put(s,System.currentTimeMillis());String[] pair=s.split("/");PriceService.reference(pair[0],pair[1],(j,e)->{if(!running||gen!=generation||j==null)return;try{if(!pair[0].equals(j.getString("base"))||!pair[1].equals(j.getString("quote")))return;long t=java.time.LocalDate.parse(j.getString("date")).atStartOfDay(java.time.ZoneOffset.UTC).toInstant().toEpochMilli();if(!prices.containsKey(s)||sources.getOrDefault(s,"").equals("Frankfurter"))acceptSnapshot(s,j.getDouble("rate"),t,"Frankfurter","Daily reference");}catch(Exception ignored){}});}
 main.postDelayed(this,60000);
 });}};snapshotPoll.run();
 }
 boolean acceptSnapshot(String s,double p,long t,String source,String state){if(!Double.isFinite(p)||p<=0||t<=0||t>System.currentTimeMillis()+300000)return false;
 if(source.equals(sources.get(s))&&t<times.getOrDefault(s,0L))return false;
 Double previous=prices.get(s);boolean sameSource=source.equals(sources.get(s));
 prices.put(s,p);times.put(s,t);sources.put(s,source);detail.put(s,state);paint(s);
 if(previous!=null&&sameSource&&Double.compare(p,previous)!=0){TextView v=values.get(s);v.setTextColor(p>previous?0xff22c55e:0xffef4444);main.postDelayed(()->{if(values.get(s)==v)v.setTextColor(WHITE);},700);}
 try{String raw=new JSONObject().put("p",p).put("t",t).put("source",source).toString();long now=System.currentTimeMillis();if(!sameSource||now-prefs.getLong("saved:"+s,0)>10000)prefs.edit().putString("q:"+s,raw).putString("provider:"+source+":"+s,raw).putLong("saved:"+s,now).apply();}catch(Exception ignored){}return true;}
 void closed(int gen){if(!running||gen!=generation)return;status.setText("Disconnected · cached quotes · retrying");for(String s:values.keySet())if(prices.containsKey(s)){detail.put(s,"Cached");paint(s);}if(heartbeat!=null)main.removeCallbacks(heartbeat);if(!kind.equals("Crypto")){startSnapshots();return;}retry=()->{if(running&&gen==generation)connect();};main.postDelayed(retry,Math.min(60000,2000L*(1L<<Math.min(5,attempts++))));}
 void quote(int gen,String s,double p,long t,String change){if(!running||gen!=generation||!values.containsKey(s)||!Double.isFinite(p)||p<=0||t<=0||t>System.currentTimeMillis()+300000||((kind.equals("Crypto")?"Binance":"Twelve Data").equals(sources.get(s))&&t<times.getOrDefault(s,0L)))return;attempts=0;Double previous=prices.get(s);prices.put(s,p);times.put(s,t);detail.put(s,"Stream "+change);sources.put(s,kind.equals("Crypto")?"Binance":"Twelve Data");paint(s);if(previous!=null&&Double.compare(p,previous)!=0){TextView v=values.get(s);v.setTextColor(p>previous?0xff22c55e:0xffef4444);main.postDelayed(()->{if(running&&gen==generation&&values.get(s)==v)v.setTextColor(WHITE);},700);}status.setText("Receiving provider quotes · see each timestamp");try{JSONObject j=new JSONObject().put("p",p).put("t",t).put("source",sources.get(s)); // throttle disk writes per symbol
 long last=prefs.getLong("saved:"+s,0);if(System.currentTimeMillis()-last>10000){prefs.edit().putString("q:"+s,j.toString()).putString("provider:"+sources.get(s)+":"+s,j.toString()).putLong("saved:"+s,System.currentTimeMillis()).apply();}}catch(Exception ignored){}}
 void paint(String s){if(!prices.containsKey(s))return;long t=times.get(s);String state=detail.get(s);if((state.startsWith("Stream")||state.startsWith("Snapshot"))&&System.currentTimeMillis()-t>(kind.equals("Crypto")?15000:120000))state="Stale / no recent tick";String date=new java.text.SimpleDateFormat("dd/MM HH:mm:ss",Locale.US).format(new Date(t));values.get(s).setText(String.format(Locale.US,"%,.8f",prices.get(s)).replaceAll("0+$","").replaceAll("\\.$","")+"\n"+state+" · "+date+"\n"+sources.getOrDefault(s,"Unknown source"));}
}
